void generate_iv(unsigned char *iv) {
    // For demonstration, using a fixed IV (not secure)
    memset(iv, 0x00, AES_BLOCK_SIZE);
}

// Function to derive a key from the provided key bytes
void derive_key(const unsigned char *input_key, size_t input_key_len, unsigned char *output_key, size_t key_len) {
    // For demonstration, using the first 'key_len' bytes of the input key
    memcpy(output_key, input_key, key_len);
}

// Function to encrypt data using AES-CBC
void encrypt_data(const unsigned char *key, size_t key_len, const unsigned char *data, size_t data_len, unsigned char *encrypted_data, size_t *encrypted_len, unsigned char *iv) {
    AES_KEY aes_key;
    AES_set_encrypt_key(key, key_len * 8, &aes_key);
    size_t blocks = (data_len + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE;
    *encrypted_len = blocks * AES_BLOCK_SIZE;
    unsigned char *out = (unsigned char *)malloc(*encrypted_len);
    AES_cbc_encrypt(data, out, data_len, &aes_key, iv, AES_ENCRYPT);
    memcpy(encrypted_data, out, *encrypted_len);
    free(out);
}

